interface CaseDefinition {
  id: `REG-${"C" | "E"}${string}`;
  title: string;
  importance: string;
  source: SourceKey;
  provenanceId: string;
  languages: string[];
  frameworks: string[];
  family: string;
  seededFailure: string;
  impact: string[];
  evidenceState?: LearningCase["pattern"]["evidenceState"];
  diagnosis: string;
  migration: string;
  oracleId: string;
  allowedEditPaths: string[];
  tenantRisk: LearningCase["security"]["tenantRisk"];
  risks: string[];
  acceptance: string;
}

function makeCase(definition: CaseDefinition): LearningCase {
  const cohort = definition.id.startsWith("REG-C") ? "common" : "edge";
  const ordinal = Number(definition.id.slice(5));
  const selectedSource = sources[definition.source];
  const fixtureStem = definition.id.toLowerCase();
  const reviewedRepositoryId = selectReviewedRepositoryId(definition);
  const reviewedRepository = admissionCandidates.find((candidate) => candidate.id === reviewedRepositoryId);

  if (reviewedRepository === undefined) {
    throw new Error(`Reviewed repository metadata is missing for ${definition.id}`);
  }

  return {
    schemaVersion: "mendpoint.learning-case.v1",
    id: definition.id,
    product: "regauge",
    cohort,
    datasetSplit: ordinal % 5 === 0 ? "holdout" : "development",
    title: definition.title,
    importance: {
      statement: definition.importance,
      frequencyClaim: "not_claimed",
      sourceIds: [selectedSource.id],
    },
    sources: [selectedSource],
    repository: {
      provenanceId: reviewedRepositoryId,
      languages: [...reviewedRepository.languages],
      frameworks: [...reviewedRepository.frameworks],
    },
    pattern: {
      family: definition.family,
      seededFailure: definition.seededFailure,
      expectedImpactGraph: definition.impact,
      evidenceState: definition.evidenceState ?? "verified",
    },
    expected: {
      diagnosis: definition.diagnosis,
      repairOrMigration: definition.migration,
      oracleIds: [definition.oracleId],
      productionAcceptance: [
        definition.acceptance,
        "The exact repository snapshot, graph, policy, authorization, model, and execution digest are bound in the run receipt.",
        "The deterministic oracle passes and no path outside the allowed edit boundary changes.",
      ],
    },
    fixture: {
      manifestId: `fixture:${fixtureStem}:v1`,
      mutationId: `mutation:${fixtureStem}:v1`,
      allowedEditPaths: allowedEditPathsByCase[definition.id] ?? definition.allowedEditPaths,
      rollbackId: `rollback:${fixtureStem}:v1`,
      cleanupId: `cleanup:${fixtureStem}:v1`,
    },
    security: {
      tenantRisk: definition.tenantRisk,
      risks: definition.risks,
      requiresDedicatedBenchmarkTenant: true,
    },
  };
}

function selectReviewedRepositoryId(definition: CaseDefinition): ReviewedRepositoryId {
  const reviewedRepositoryId = reviewedRepositoryIdByCase[definition.id] ?? (definition.provenanceId === "repo-opentelemetry-demo"
    ? reviewedRepositoryIdForOpenTelemetryPattern[definition.family]
    : reviewedRepositoryIdByResearchCandidate[definition.provenanceId]);

  if (reviewedRepositoryId === undefined) {
    throw new Error(`No reviewed repository mapping for ${definition.id}`);
  }
  return reviewedRepositoryId;
}

