function c(
  id: CaseDefinition["id"],
  title: string,
  importance: string,
  sourceKey: SourceKey,
  provenanceId: string,
  languages: string[],
  frameworks: string[],
  family: string,
  seededFailure: string,
  impact: string[],
  diagnosis: string,
  migration: string,
  oracleId: string,
  allowedEditPaths: string[],
  tenantRisk: LearningCase["security"]["tenantRisk"],
  risks: string[],
  acceptance: string,
): CaseDefinition {
  return {
    id,
    title,
    importance,
    source: sourceKey,
    provenanceId,
    languages,
    frameworks,
    family,
    seededFailure,
    impact,
    diagnosis,
    migration,
    oracleId,
    allowedEditPaths,
    tenantRisk,
    risks,
    acceptance,
  };
}

